ns16:scriptTask.ns16:script:
tw.local.odcRequest.stepLog = {};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step = ""+tw.epv.ScreenNames.CACT07; 

 tw.local.odcRequest.appInfo.stepName= tw.epv.ScreenNames.CACT07;
 tw.local.odcRequest.appInfo.appID = tw.system.processInstance.id;
 
 tw.local.actionConditions = {};
tw.local.actionConditions.complianceApproval= tw.local.odcRequest.complianceApproval;
tw.local.actionConditions.screenName= tw.epv.ScreenNames.CACT07;
tw.local.actionConditions.userRole= tw.local.odcRequest.initiator;
tw.local.actionConditions.lastStepAction= tw.epv.ScreenNames.CACT03;

/*Visibilty Conditions*/
/*Basic Details CV Visibility*/
///////////////////////////////
if(tw.local.odcRequest.requestNature.value == "update"){
	tw.local.parentRequestNoVIS = "READONLY";
}	
else{
	tw.local.parentRequestNoVIS = "None";
}	
if(tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Create ||tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate  || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment){
	tw.local.contractStageVIS = "READONLY";
}
else{
tw.local.contractStageVIS = "NONE";
}

if(tw.local.documentGenerated == true)
	tw.local.remittanceLetterListVIS = "EDITABLE";
else
	tw.local.remittanceLetterListVIS = "NONE";
//if(tw.local.fromTradeFo == true)
//{
//	tw.local.tradefoVis = "Editable";
//	tw.local.exehubMkrVis = "None";
//}
//else
//{
//	tw.local.tradefoVis = "None";
//	tw.local.exehubMkrVis = "Editable";
//}
 tw.local.requestAmend = "" + tw.epv.RequestType.Amendment;
 tw.local.requestRecreate = "" + tw.epv.RequestType.Recreate;

if(tw.local.compApprovalInit == tw.epv.userRole.CACT03)
{
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToRequester)
	{
		tw.local.odcRequest.appInfo.status     =" In Approval ";
		tw.local.odcRequest.appInfo.subStatus  ="Pending Trade FO Review";
		tw.local.compApprovalInit = tw.epv.userRole.CACT03
	}
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest)
	{
		tw.local.odcRequest.appInfo.status          = "In Execution";
		tw.local.odcRequest.appInfo.subStatus       = "Pending Execution Hub Processing";
		tw.local.compApprovalInit = tw.epv.userRole.CACT03
	}
	
}

else if (tw.local.compApprovalInit == "EXE")
{
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToRequester)
	{
		tw.local.odcRequest.appInfo.status          = "In Execution";
		tw.local.odcRequest.appInfo.subStatus       = "Pending Execution Hub Processing";
		tw.local.compApprovalInit = "EXE";
		console.log("EXEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEe");
	}
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest)
	{
		tw.local.odcRequest.appInfo.status          = "In Execution";
		tw.local.odcRequest.appInfo.subStatus       = "Pending Execution Hub Processing";
		tw.local.compApprovalInit = "EXE";
		console.log("EXEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEe");
	}
	
}
if(tw.local.fromCompRep == true)
{
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToRequester)
	{
		tw.local.odcRequest.appInfo.status     =" Initiated ";
		tw.local.odcRequest.appInfo.subStatus  ="Pending Compliance Rep Initiation Review";
	}
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest)
	{
		tw.local.odcRequest.appInfo.status          = "In Approval";
		tw.local.odcRequest.appInfo.subStatus       = "Awaiting Trade FO Approval";
		tw.local.compApprovalInit = "";
	}
}
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Closure)
{
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToRequester)
	{
		tw.local.odcRequest.appInfo.status     =" Initiated ";
		tw.local.odcRequest.appInfo.subStatus  ="Pending Compliance Rep Initiation Review";
	}
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest)
	{
		tw.local.odcRequest.appInfo.status          = "In Approval";
		tw.local.odcRequest.appInfo.subStatus       = "Awaiting Trade FO Approval";	
	}
}

 tw.local.errorMessage ="";
 var mandatoryTriggered = false;
 
 
 
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToMaker || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToRequester)
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason , "tw.local.odcRequest.stepLog.returnReason", 80 , "Shouldn't be more than 80 character" , " Return Reason : " + "Shouldn't be more than 80 character" );
	
//-------------------------------------------------Trade Fo and compliance comment validation ------------------------------
if(tw.local.odcRequest.complianceApproval == true)
mandatory(tw.local.odcRequest.compcheckerComment, "tw.local.odcRequest.compcheckerComment");

function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{			
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
	
			default:
				
				// VALIDATE DATE OBJECT
				if( field && field.getTime && isFinite(field.getTime()) ) {}
				
				else
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;	
				}
		}
	}
	return true;
}

function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}
function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field && field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}
	
	maxLength(tw.local.odcRequest.stepLog.comment , "tw.local.odcRequest.stepLog.comment",500 , "Shouldn't be more than 500 character" , " Comment : " + "Shouldn't be more than 5000 character" );
	tw.local.errorMessage ="";

